#include <iostream>
struct Base {
    virtual void f() { std::cout << "Base::f "; }
    virtual void g() final { std::cout << "Base::g "; }   // final：禁止派生覆盖
};
struct Derived : Base {
    void f() override { std::cout << "Derived::f "; }     // 覆盖 f
    // void g() override;  // 错误：Base::g 是 final，不能覆盖
};
int main() {
    Derived d;
    Base& b = d;
    b.f(); b.g();
    std::cout << '\n';
}
